<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api,user,message} from '../api'
const route=useRoute(),mine=computed(()=>route.query.mine==='1'),items=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref('')
async function load(p=1){loading.value=true;error.value='';try{const r=await api.get(mine.value?'/member/collections':'/public/collections',{params:{page:p,author:route.query.author}});items.value=mine.value?r.data:r.data.items;total.value=mine.value?r.data.length:r.data.total;page.value=p}catch(e){error.value=message(e)}finally{loading.value=false}}
watch(()=>route.query,()=>load(),{immediate:true})
</script>
<template><div class="container page-space"><div class="section-heading"><div><p class="eyebrow">文学社 / 合集</p><h1 class="page-title">{{mine?'我的合集':'合集'}}</h1></div><RouterLink v-if="user" to="/collection-edit" class="button">新建合集</RouterLink></div><p v-if="error" class="error-message">{{error}}</p><div v-if="loading" class="empty-state">加载中…</div><div v-else class="collection-grid"><RouterLink v-for="(c,i) in items" :key="c.id" :to="`/collection/${c.id}`" class="collection-card"><span class="collection-spine">{{String((page-1)*12+i+1).padStart(2,'0')}}</span><div><span class="genre-label">{{c.kind}}{{mine&&!c.published?' · 私密':''}}</span><h2>{{c.title}}</h2><p>{{c.description||'暂无简介'}}</p><small>{{c.authorName}} · {{c.workCount}} 篇已发布</small></div></RouterLink></div><p v-if="!loading&&!error&&!items.length" class="empty-state">暂无合集</p><div v-if="!mine&&total>12" class="pagination"><button :disabled="loading||page===1" @click="load(page-1)">上一页</button><span>{{page}} / {{Math.ceil(total/12)}}</span><button :disabled="loading||page*12>=total" @click="load(page+1)">下一页</button></div></div></template>
